package com.ias.identity.auth;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class DomainPolicyTest {
 @Test void roleNameOrIdentityTypeNeverCreatesCapabilities(){assertFalse(DomainPolicy.allowed("EMPLOYEE",List.of(),"APPROVAL_REVIEW"));assertFalse(DomainPolicy.allowed("CUSTOMER",DomainPolicy.CAPABILITIES,"APPROVAL_READ"));assertFalse(DomainPolicy.allowed("PLATFORM",DomainPolicy.CAPABILITIES,"STOCK_READ"));}
 @Test void submitCatalogAndReviewHaveIndependentRequirements(){var engineer=Set.of("approval.parts.read","approval.parts.submit","ticket.engineer.read","ticket.record");assertTrue(DomainPolicy.allowed("EMPLOYEE",engineer,"APPROVAL_SUBMIT"));assertTrue(DomainPolicy.allowed("EMPLOYEE",engineer,"STOCK_CATALOG"));assertFalse(DomainPolicy.allowed("EMPLOYEE",engineer,"APPROVAL_REVIEW"));assertFalse(DomainPolicy.allowed("EMPLOYEE",engineer,"STOCK_READ"));assertTrue(DomainPolicy.allowed("EMPLOYEE",Set.of("approval.parts.read","approval.parts.review","ticket.read"),"APPROVAL_REVIEW"));}
 @Test void managementDoesNotBorrowSubmissionOrReview(){assertTrue(DomainPolicy.allowed("EMPLOYEE",Set.of("stock.read","stock.manage"),"STOCK_MANAGE"));assertFalse(DomainPolicy.allowed("EMPLOYEE",Set.of("stock.manage"),"STOCK_MANAGE"));assertFalse(DomainPolicy.allowed("EMPLOYEE",Set.of("stock.read","stock.manage"),"APPROVAL_READ"));}
 @Test void ownNotificationDoesNotGrantBusinessAccess(){assertTrue(DomainPolicy.allowed("CUSTOMER",List.of(),"NOTIFICATION_READ"));assertTrue(DomainPolicy.allowed("EMPLOYEE",List.of(),"NOTIFICATION_WRITE"));assertFalse(DomainPolicy.allowed("PLATFORM",List.of(),"NOTIFICATION_READ"));assertFalse(DomainPolicy.allowed("CUSTOMER",List.of(),"APPROVAL_SUBMIT"));}
 @Test void mutationsRequireExplicitCsrfEvenThoughReadQualificationProbeIsSeparate(){assertTrue(DomainPolicy.write("APPROVAL_SUBMIT"));assertTrue(DomainPolicy.write("APPROVAL_REVIEW"));assertTrue(DomainPolicy.write("STOCK_MANAGE"));assertTrue(DomainPolicy.write("NOTIFICATION_WRITE"));assertFalse(DomainPolicy.write("STOCK_CATALOG"));assertFalse(DomainPolicy.write("APPROVAL_READ"));assertFalse(DomainPolicy.allowed("EMPLOYEE",DomainPolicy.CAPABILITIES,"UNKNOWN"));}
 @Test void financeRequiresExplicitCapabilityEvenForCurrentCustomerOrEmployee(){assertFalse(DomainPolicy.allowed("CUSTOMER",List.of(),"FINANCE_READ"));assertFalse(DomainPolicy.allowed("EMPLOYEE",List.of(),"FINANCE_WRITE"));assertTrue(DomainPolicy.allowed("CUSTOMER",Set.of("finance.quote.read","finance.quote.confirm"),"FINANCE_WRITE"));assertFalse(DomainPolicy.allowed("CUSTOMER",Set.of("finance.quote.read","finance.quote.write"),"FINANCE_WRITE"));assertTrue(DomainPolicy.allowed("EMPLOYEE",Set.of("finance.quote.read","finance.quote.write"),"FINANCE_WRITE"));assertFalse(DomainPolicy.allowed("PLATFORM",DomainPolicy.CAPABILITIES,"FINANCE_READ"));assertTrue(DomainPolicy.write("FINANCE_WRITE"));assertFalse(DomainPolicy.write("FINANCE_READ"));}}
